use vstd::prelude::*;

verus! {

fn remove_front(a: &Vec<i32>) -> (out: Vec<i32>)
    requires
        a.len() > 0,
    ensures
        // length is exactly one less
        out.len() == a.len() - 1,
        // order preserved: out[i] == a[i+1]
        forall|i: int| 0 <= i < out.len() ==> out[i] == a[i + 1],
        // input not modified (contents unchanged)
        forall|i: int| 0 <= i < a.len() ==> a[i] == old(a[i]),
{
    let n = a.len();
    let mut out: Vec<i32> = Vec::new();

    let mut i: usize = 1;
    while i < n
        invariant
            1 <= i <= n,
            out.len() == i - 1,
            forall|j: int| 0 <= j < out.len() ==> out[j] == a[j + 1],
            forall|k: int| 0 <= k < a.len() ==> a[k] == old(a[k]),
        decreases
            n - i,
    {
        // push a[i] into out, at position i-1
        out.push(a[i]);
        i = i + 1;
    }

    out
}

} // verus!

